CREATE TABLE job_definitions (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), environment_id uuid NOT NULL REFERENCES environments(id), name text NOT NULL, handler text NOT NULL, trigger jsonb NOT NULL, effect_policy text NOT NULL CHECK(effect_policy IN ('read_only','idempotent','protected')), limits jsonb NOT NULL, revision integer NOT NULL DEFAULT 0 CHECK(revision >= 0), hash text NOT NULL, paused boolean NOT NULL DEFAULT false, next_fire_at timestamptz, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE UNIQUE INDEX job_definitions_cell_name_key ON job_definitions(environment_id, name);
CREATE TABLE job_runs (id uuid PRIMARY KEY, definition_id uuid NOT NULL REFERENCES job_definitions(id), project_id uuid NOT NULL REFERENCES projects(id), environment_id uuid NOT NULL REFERENCES environments(id), run_id uuid UNIQUE REFERENCES execution_runs(id), state text NOT NULL CHECK(state IN ('queued','running','succeeded','failed','cancel_requested','cancelled','unknown','reconciling')), trigger text NOT NULL CHECK(trigger IN ('cron','event','manual')), dedupe_key text NOT NULL, payload_ref uuid, attempt integer NOT NULL DEFAULT 1 CHECK(attempt >= 0), scheduled_for timestamptz NOT NULL, started_at timestamptz, finished_at timestamptz, reason text, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE UNIQUE INDEX job_runs_dedupe_key ON job_runs(definition_id, dedupe_key);
CREATE INDEX job_runs_state_idx ON job_runs(state, created_at);
CREATE TABLE job_outbox (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), environment_id uuid NOT NULL REFERENCES environments(id), job_run_id uuid REFERENCES job_runs(id), effect_key text NOT NULL, destination text NOT NULL, state text NOT NULL CHECK(state IN ('pending','dispatching','delivered','failed','unknown','reconciling','held')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts >= 0), payload jsonb NOT NULL, payload_hash text NOT NULL, last_error text, evidence_ref text, claimed_at timestamptz, created_at timestamptz NOT NULL, settled_at timestamptz);
CREATE UNIQUE INDEX job_outbox_effect_key ON job_outbox(environment_id, effect_key);
CREATE INDEX job_outbox_state_idx ON job_outbox(state, created_at);
